		'polls' => array( 'en' => 'Hours vary by town and city. Polls open by 11 a.m. and close no earlier than 7 p.m., and many open earlier. Your town or city clerk has the exact hours.', 'es' => 'El horario cambia según el municipio o la ciudad. Los lugares de votación abren a más tardar a las 11 a. m. y cierran a las 7 p. m. o después, y muchos abren antes. El secretario de tu municipio o ciudad (town or city clerk) tiene el horario exacto.', 'src' => 'https://gc.nh.gov/rsa/html/LXIII/659/659-4.htm' ),
		'id' => array( 'en' => 'Yes. Show a valid photo ID, such as a driver\'s license from any state, a state ID card, a U.S. military ID, or a U.S. passport. Without one, an election official must confirm who you are before you can vote. Student IDs aren\'t accepted for this election.', 'es' => 'Sí. Muestra una identificación válida con foto, como una licencia de conducir de cualquier estado, una tarjeta de identificación estatal, una identificación militar de EE. UU. o un pasaporte de EE. UU. Si no tienes una, un funcionario electoral debe confirmar quién eres antes de que puedas votar. Las identificaciones de estudiante no se aceptan en esta elección.', 'src' => 'https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/10-23-26-student-id-press-release.pdf' ),
		'reg' => array( 'en' => 'Yes. Register at your polling place on Election Day, or with your town or city clerk until 6 to 13 days before the election (the date varies by town). Bring proof of identity, age, U.S. citizenship and domicile.', 'es' => 'Sí. Regístrate en tu lugar de votación el Día de las Elecciones, o con el secretario de tu municipio o ciudad (town or city clerk) hasta 6 a 13 días antes de la elección (la fecha cambia según el municipio). Lleva comprobantes de identidad, edad, ciudadanía estadounidense y domicilio.', 'src' => 'https://www.sos.nh.gov/elections/register-vote' ),
		'selfie' => array( 'en' => 'Yes, your own ballot. A federal appeals court struck down New Hampshire\'s ballot selfie ban in 2016. Don\'t photograph other voters or their ballots.', 'es' => 'Sí, tu propia boleta. Una corte federal de apelaciones anuló en 2016 la prohibición de New Hampshire de tomarse selfies con la boleta. No tomes fotos de otros votantes ni de sus boletas.', 'src' => 'https://media.ca1.uscourts.gov/pdf.opinions/15-2021P-01A.pdf' ),
	),
	'NJ' => array(
		'polls' => array( 'en' => 'Polls are open 6 a.m. to 8 p.m. In-person early voting runs October 24 to November 1.', 'es' => 'Los lugares de votación abren de 6 a. m. a 8 p. m. La votación anticipada en persona es del 24 de octubre al 1 de noviembre.', 'src' => 'https://www.nj.gov/state/elections/assets/pdf/posters-bill-of-rights/2026-11-bill-of-rights-poster-english.pdf' ),
		'id' => array( 'en' => 'Usually not. Some first-time voters who registered by mail without a verified ID number must show ID, such as a driver\'s license or a utility bill, or vote a provisional ballot.', 'es' => 'Por lo general, no. Algunos votantes nuevos que se registraron por correo sin un número de identificación verificado deben mostrar una identificación, como una licencia de conducir o un recibo de servicios, o votar con una boleta provisional.', 'src' => 'https://www.nj.gov/state/elections/assets/pdf/posters-bill-of-rights/2026-11-bill-of-rights-poster-english.pdf' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 13, 2026, and New Jersey has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 13 de octubre de 2026, y New Jersey no tiene registro el Día de las Elecciones.', 'src' => 'https://www.nj.gov/state/elections/voter-registration.shtml' ),
		'selfie' => array( 'en' => 'Not at the polls. New Jersey law bars showing your ballot inside the polling room.', 'es' => 'No en el lugar de votación. La ley de New Jersey prohíbe mostrar tu boleta dentro de la sala de votación.', 'src' => 'https://www.nj.gov/state/dos-statutes-elections-19-31-39.shtml' ),
	),
	'NM' => array(
		'polls' => array( 'en' => 'Polling places are open 7 a.m. to 7 p.m. Mailed ballots must arrive by 7 p.m. on Election Day.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m. Las boletas enviadas por correo deben llegar a más tardar a las 7 p. m. del Día de las Elecciones.', 'src' => 'https://www.sos.nm.gov/wp-content/uploads/2026/06/2026-Important-General-Election-Dates.pdf' ),
		'id' => array( 'en' => 'Usually not. You state your name, year of birth, and registered address. First-time voters who registered by mail without ID must show one, such as a photo ID or a utility bill.', 'es' => 'Por lo general, no. Dices tu nombre, tu año de nacimiento y la dirección con la que te registraste. Los votantes nuevos que se registraron por correo sin identificación deben mostrar una, como una identificación con foto o un recibo de servicios.', 'src' => 'https://www.sos.nm.gov/voting-and-elections/voting-faqs/voting/' ),
		'reg' => array( 'en' => 'Yes. Regular registration closed October 6, 2026, but you can register and vote the same day at your County Clerk\'s office, some early voting sites, or any polling place in your county on Election Day.', 'es' => 'Sí. El registro regular cerró el 6 de octubre de 2026, pero puedes registrarte y votar el mismo día en la oficina del secretario de tu condado (County Clerk), en algunos centros de votación anticipada o en cualquier lugar de votación de tu condado el Día de las Elecciones.', 'src' => 'https://www.sos.nm.gov/voting-and-elections/voting-faqs/same-day-voter-registration-faq/' ),
	),
	'NY' => array(
		'polls' => array( 'en' => 'Polls are open 6 a.m. to 9 p.m. Early voting runs October 24 to November 1, with hours set by each county.', 'es' => 'Los lugares de votación abren de 6 a. m. a 9 p. m. La votación anticipada es del 24 de octubre al 1 de noviembre, con horarios que fija cada condado.', 'src' => 'https://elections.ny.gov/system/files/documents/2026/08/508_2026-state-of-new-york-election-law_v2.pdf' ),
		'id' => array( 'en' => 'Usually not; you sign the poll book. Some first-time voters who registered by mail may need a photo ID, a utility bill, a bank statement, or a paycheck.', 'es' => 'Por lo general, no; firmas el registro de votantes. Algunos votantes nuevos que se registraron por correo podrían necesitar una identificación con foto, un recibo de servicios, un estado de cuenta bancario o un talón de pago.', 'src' => 'https://elections.ny.gov/system/files/documents/2026/08/508_2026-state-of-new-york-election-law_v2.pdf' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. Your application had to reach your county board of elections by October 24, 2026, and New York has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. Tu solicitud tenía que llegar a la junta electoral de tu condado (county board of elections) a más tardar el 24 de octubre de 2026, y New York no tiene registro el Día de las Elecciones.', 'src' => 'https://elections.ny.gov/system/files/documents/2025/12/2026-political-calendar-quad-fold-12.9.2025-final.pdf' ),
		'selfie' => array( 'en' => 'No. New York law makes it a misdemeanor to show your marked ballot to anyone in a way that reveals your votes, and that includes a ballot selfie.', 'es' => 'No. En New York es un delito menor mostrar tu boleta marcada a cualquier persona de una forma que revele tus votos, y eso incluye una selfie con tu boleta.', 'src' => 'https://elections.ny.gov/system/files/documents/2026/08/508_2026-state-of-new-york-election-law_v2.pdf' ),
	),
	'NC' => array(
		'polls' => array( 'en' => 'Polling places are open 6:30 a.m. to 7:30 p.m. If you\'re in line at 7:30 p.m., you can still vote.', 'es' => 'Los lugares de votación abren de 6:30 a. m. a 7:30 p. m. Si estás en la fila a las 7:30 p. m., todavía puedes votar.', 'src' => 'https://www.ncsbe.gov/voting/vote-person-election-day' ),
		'id' => array( 'en' => 'You\'ll be asked for a photo ID, such as a North Carolina driver\'s license, a U.S. passport, or a free voter photo ID card. If you can\'t show one, you can still vote by filling out an ID Exception Form.', 'es' => 'Te pedirán una identificación con foto, como una licencia de conducir de North Carolina, un pasaporte de EE. UU. o una credencial gratuita de votante con foto. Si no puedes mostrar una, todavía puedes votar si llenas un formulario de excepción de identificación (ID Exception Form).', 'src' => 'https://www.ncsbe.gov/voting/voter-id' ),
		'reg' => array( 'en' => 'Yes, during early voting, through October 31. You can register and vote at the same time at an early voting site, but not on Election Day.', 'es' => 'Sí, durante la votación anticipada, hasta el 31 de octubre. Puedes registrarte y votar al mismo tiempo en un centro de votación anticipada, pero no el Día de las Elecciones.', 'src' => 'https://www.ncsbe.gov/registering/how-register', 'until' => '2026-10-31', 'en_after' => 'No, not for the November 3 election. Same-day registration ended with early voting on October 31, and North Carolina has no Election Day registration.', 'es_after' => 'No para la elección del 3 de noviembre. El registro el mismo día terminó con la votación anticipada el 31 de octubre, y North Carolina no tiene registro el Día de las Elecciones.' ),
		'selfie' => array( 'en' => 'No. North Carolina law bars photographing a voted ballot. It also bars photographing voters in the voting area without their permission and the chief judge\'s.', 'es' => 'No. La ley de North Carolina prohíbe tomarle foto a una boleta votada. También prohíbe tomar fotos de los votantes en el área de votación sin su permiso y el del juez principal (chief judge).', 'src' => 'https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_163/GS_163-166.3.html' ),
	),
	'ND' => array(
		'polls' => array( 'en' => 'Hours vary by county or city. Polls open between 7 a.m. and 9 a.m. and close between 7 p.m. and 9 p.m. local time. North Dakota has two time zones.', 'es' => 'El horario cambia según el condado o la ciudad. Los lugares de votación abren entre las 7 a. m. y las 9 a. m. y cierran entre las 7 p. m. y las 9 p. m., hora local. North Dakota tiene dos zonas horarias.', 'src' => 'https://ndlegis.gov/cencode/t16-1c01.pdf' ),
		'id' => array( 'en' => 'Yes. Show a North Dakota driver\'s license, nondriver ID card, or tribal ID with your name, current North Dakota address, and birth date. A utility bill or bank statement can fill in missing details.', 'es' => 'Sí. Muestra una licencia de conducir de North Dakota, una tarjeta de identificación para no conductores o una identificación tribal con tu nombre, tu dirección actual en North Dakota y tu fecha de nacimiento. Un recibo de servicios o un estado de cuenta bancario puede completar los datos que falten.', 'src' => 'https://ndlegis.gov/cencode/t16-1c01.pdf' ),
		'reg' => array( 'en' => 'You don\'t need to. North Dakota has no voter registration. If you\'re eligible, bring a valid ID with your current address and vote.', 'es' => 'No hace falta. North Dakota no tiene registro de votantes. Si cumples los requisitos, lleva una identificación válida con tu dirección actual y vota.', 'src' => 'https://www.sos.nd.gov/elections/voter/voting-north-dakota' ),
	),
	'OH' => array(
		'polls' => array( 'en' => 'Polls are open 6:30 a.m. to 7:30 p.m., and you vote at your assigned polling place.', 'es' => 'Los lugares de votación abren de 6:30 a. m. a 7:30 p. m., y votas en el lugar de votación que te corresponde.', 'src' => 'https://www.ohiosos.gov/elections' ),
		'id' => array( 'en' => 'Yes. Show an unexpired photo ID, such as an Ohio driver\'s license, a state ID card, a U.S. passport, or a military ID. Without one, you vote a provisional ballot.', 'es' => 'Sí. Muestra una identificación vigente con foto, como una licencia de conducir de Ohio, una tarjeta de identificación estatal, un pasaporte de EE. UU. o una identificación militar. Si no tienes una, votas con una boleta provisional.', 'src' => 'https://www.ohiosos.gov/elections' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 5, 2026, and Ohio has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 5 de octubre de 2026, y Ohio no tiene registro el Día de las Elecciones.', 'src' => 'https://www.ohiosos.gov/elections/frequently-asked-questions' ),
	),
	'OK' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 7 p.m.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m.', 'src' => 'https://oklahoma.gov/elections/voters/how-to-vote.html' ),
		'id' => array( 'en' => 'Yes. Show a current photo ID, such as a driver\'s license, or the free voter ID card your county election board mailed you. Without either, you can sign an affidavit and vote a provisional ballot.', 'es' => 'Sí. Muestra una identificación vigente con foto, como una licencia de conducir, o la tarjeta gratuita de votante que te envió por correo la junta electoral de tu condado. Si no tienes ninguna, puedes firmar una declaración jurada y votar con una boleta provisional.', 'src' => 'https://oklahoma.gov/elections/voters/proof-of-identity.html' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 9, 2026, and Oklahoma has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 9 de octubre de 2026, y Oklahoma no tiene registro el Día de las Elecciones.', 'src' => 'https://oklahoma.gov/elections/voters/voting-101.html' ),
		'selfie' => array( 'en' => 'Yes. You can take a picture of your marked ballot, but don\'t post or share it until you\'re outside the area where you check in and vote.', 'es' => 'Sí. Puedes tomarle foto a tu boleta marcada, pero no la publiques ni la compartas hasta que salgas del área donde te registras y votas.', 'src' => 'https://oklahoma.gov/elections/voters/voting-101.html' ),
	),
	'GA' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 7 p.m. at your assigned polling place. If you\'re in line by 7 p.m., you can still vote.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m. en el lugar que te corresponde. Si estás en la fila a las 7 p. m., todavía puedes votar.', 'src' => 'https://sos.ga.gov/how-to-guide/how-guide-voting' ),
		'id' => array( 'en' => 'Yes. Show a photo ID, such as a Georgia driver\'s license, even if it\'s expired, a U.S. passport, or a free Georgia voter ID card from your county registrar.', 'es' => 'Sí. Muestra una identificación con foto, como una licencia de conducir de Georgia, aunque esté vencida, un pasaporte de EE. UU. o una credencial gratuita de votante de Georgia de la oficina de registro de tu condado (county registrar).', 'src' => 'https://sos.ga.gov/page/georgia-voter-identification-requirements' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 5, 2026, and Georgia has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 5 de octubre de 2026, y Georgia no tiene registro el Día de las Elecciones.', 'src' => 'https://libertycountyga.gov/555/Election-Calendar' ),
		'selfie' => array( 'en' => 'Not at the polls. Georgia law bars using cameras or cell phones in a polling place while voting is going on, unless a poll manager allows it.', 'es' => 'No en el lugar de votación. La ley de Georgia prohíbe usar cámaras o celulares en un lugar de votación mientras se está votando, salvo que el encargado de la casilla (poll manager) lo permita.', 'src' => 'https://cms.chathamcountyga.gov/api/assets/elections-website/a69d420c-4fdc-4a21-9b81-f541ae59a167/media-photography-policy.pdf?version=0' ),
	),
	'HI' => array(
		'mail' => array( 'en' => 'Hawaii votes by mail. Your ballot must be received by 7 p.m. on November 3, and a postmark isn\'t enough. Voter service centers are open 7 a.m. to 7 p.m. that day for in-person voting.', 'es' => 'Hawaii vota por correo. Tu boleta debe recibirse a más tardar a las 7 p. m. del 3 de noviembre, y el matasellos no basta. Los centros de servicio al votante abren de 7 a. m. a 7 p. m. ese día para votar en persona.', 'src' => 'https://elections.hawaii.gov/voters/voter-service-centers-and-places-of-deposit/' ),
		'id' => array( 'en' => 'Usually not. At a voter service center, a clerk may ask you to confirm who you are, for example with a photo ID.', 'es' => 'Por lo general, no. En un centro de servicio al votante, un empleado puede pedirte que confirmes quién eres, por ejemplo con una identificación con foto.', 'src' => 'https://elections.hawaii.gov/wp-content/uploads/HAR-Office-of-Elections-1.pdf' ),
		'reg' => array( 'en' => 'Yes. You can register and vote the same day at a voter service center, open October 20 through November 3.', 'es' => 'Sí. Puedes registrarte y votar el mismo día en un centro de servicio al votante, abierto del 20 de octubre al 3 de noviembre.', 'src' => 'https://elections.hawaii.gov/voters/registration/' ),
	),
	'ID' => array(
		'polls' => array( 'en' => 'Polls are open 8 a.m. to 8 p.m. local time, and some counties open at 7 a.m. Idaho has two time zones.', 'es' => 'Los lugares de votación abren de 8 a. m. a 8 p. m., hora local, y algunos condados abren a las 7 a. m. Idaho tiene dos zonas horarias.', 'src' => 'https://legislature.idaho.gov/statutesrules/idstat/title34/t34ch11/sect34-1101/' ),
		'id' => array( 'en' => 'You\'ll be asked for a photo ID, such as an Idaho driver\'s license, a U.S. passport, or a tribal ID. If you don\'t have one, you can sign an identity affidavit instead.', 'es' => 'Te pedirán una identificación con foto, como una licencia de conducir de Idaho, un pasaporte de EE. UU. o una identificación tribal. Si no tienes una, puedes firmar una declaración jurada de identidad en su lugar.', 'src' => 'https://voteidaho.gov/guide-to-vote-in-person/' ),
		'reg' => array( 'en' => 'Yes. Preregistration closed October 23, 2026. You can still register and vote in person during early voting or on Election Day with a photo ID and proof of where you live.', 'es' => 'Sí. El registro previo cerró el 23 de octubre de 2026. Todavía puedes registrarte y votar en persona durante la votación anticipada o el Día de las Elecciones con una identificación con foto y un comprobante de domicilio.', 'src' => 'https://voteidaho.gov/voter-registration/' ),
	),
	'IL' => array(
		'polls' => array( 'en' => 'Polls are open 6 a.m. to 7 p.m.', 'es' => 'Los lugares de votación abren de 6 a. m. a 7 p. m.', 'src' => 'https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=001000050K17-1' ),
		'id' => array( 'en' => 'Usually not; most voters give their name and sign in. If you first registered by mail and haven\'t proven your identity yet, you may need to show ID.', 'es' => 'Por lo general, no; la mayoría de los votantes dan su nombre y firman. Si te registraste por primera vez por correo y todavía no has comprobado tu identidad, es posible que tengas que mostrar una identificación.', 'src' => 'https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=001000050K17-9' ),
		'reg' => array( 'en' => 'Yes. Online registration closed October 18, 2026. You can still register and vote in person at grace period sites through Election Day.', 'es' => 'Sí. El registro en línea cerró el 18 de octubre de 2026. Todavía puedes registrarte y votar en persona en los lugares del periodo de gracia (grace period) hasta el Día de las Elecciones.', 'src' => 'https://www.elections.il.gov/NewDocDisplay.aspx?%2fM0cs48zOKVZyk9eAbpEoxjoGz9b5YaGE%2bEuf7JVd2Tlx2Mybp2RbacEJVh848tnFOLoTd3G4cRsCxSj%2bcrL1MmhG9QsYgJ9XEPk5RBnskXetvBKqlqFjTKgx7qP9eeYvjYVE4PHXwpZnTFFeskkj9bQfLeonJZF' ),
	),
	'IN' => array(
		'polls' => array( 'en' => 'Polls are open 6 a.m. to 6 p.m. local time. Indiana has two time zones.', 'es' => 'Los lugares de votación abren de 6 a. m. a 6 p. m., hora local. Indiana tiene dos zonas horarias.', 'src' => 'https://www.in.gov/dA/a8ee46432d/2026-Election-Day-Handbook.pdf?language_id=1' ),
		'id' => array( 'en' => 'Yes. Show a current photo ID issued by Indiana or the U.S. government, such as a driver\'s license or a U.S. passport. Without one, you vote a provisional ballot and have until noon 10 days after the election to follow up with your county election board.', 'es' => 'Sí. Muestra una identificación vigente con foto emitida por Indiana o por el gobierno de EE. UU., como una licencia de conducir o un pasaporte de EE. UU. Si no tienes una, votas con una boleta provisional y tienes hasta el mediodía del décimo día después de la elección para completar el trámite con la junta electoral de tu condado.', 'src' => 'https://www.in.gov/sos/elections/voter-information/photo-id-law/' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 5, 2026, and Indiana has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 5 de octubre de 2026, y Indiana no tiene registro el Día de las Elecciones.', 'src' => 'https://www.in.gov/sos/elections/voter-information/register-to-vote/' ),
	),
	'IA' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 8 p.m.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m.', 'src' => 'https://www.legis.iowa.gov/docs/code/49.73.pdf' ),
		'id' => array( 'en' => 'Yes. Show an ID such as an Iowa driver\'s license, a U.S. passport, or the free Iowa Voter ID Card. Without one, another registered voter can vouch for you.', 'es' => 'Sí. Muestra una identificación, como una licencia de conducir de Iowa, un pasaporte de EE. UU. o la credencial gratuita Iowa Voter ID Card. Si no tienes una, otro votante registrado puede dar fe de quién eres.', 'src' => 'https://sos.iowa.gov/voters/voter-id-faq' ),
		'reg' => array( 'en' => 'Yes. Preregistration closed October 19, 2026. You can still register and vote at your polling place on Election Day with ID and proof of where you live.', 'es' => 'Sí. El registro previo cerró el 19 de octubre de 2026. Todavía puedes registrarte y votar en tu lugar de votación el Día de las Elecciones con una identificación y un comprobante de domicilio.', 'src' => 'https://sos.iowa.gov/voters/election-day' ),
		'selfie' => array( 'en' => 'Yes, with limits. Iowa bans photos and showing your voted ballot only when it\'s for an illegal purpose or it interferes with other voters or the polling place.', 'es' => 'Sí, con límites. Iowa prohíbe las fotos y mostrar tu boleta votada solo cuando es con un fin ilegal o cuando interfiere con otros votantes o con el lugar de votación.', 'src' => 'https://www.legis.iowa.gov/docs/code/49.pdf' ),
	),
	'KS' => array(
		'polls' => array( 'en' => 'Polls are open at least 7 a.m. to 7 p.m. Counties can open as early as 6 a.m. and close as late as 8 p.m., so check your county\'s hours.', 'es' => 'Los lugares de votación abren por lo menos de 7 a. m. a 7 p. m. Los condados pueden abrir desde las 6 a. m. y cerrar hasta las 8 p. m., así que revisa el horario de tu condado.', 'src' => 'https://sos.ks.gov/elections/voter-information.html' ),
		'id' => array( 'en' => 'Yes. Show a photo ID, such as a driver\'s license or a U.S. passport. Without one, you vote a provisional ballot.', 'es' => 'Sí. Muestra una identificación con foto, como una licencia de conducir o un pasaporte de EE. UU. Si no tienes una, votas con una boleta provisional.', 'src' => 'https://sos.ks.gov/elections/election-faq.html' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 13, 2026, and Kansas has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 13 de octubre de 2026, y Kansas no tiene registro el Día de las Elecciones.', 'src' => 'https://sos.ks.gov/elections/election-faq.html' ),
	),
	'KY' => array(
		'polls' => array( 'en' => 'Polls are open 6 a.m. to 6 p.m. local time. Kentucky has two time zones.', 'es' => 'Los lugares de votación abren de 6 a. m. a 6 p. m., hora local. Kentucky tiene dos zonas horarias.', 'src' => 'https://elect.ky.gov/Voters/Pages/Voting-In-Person-and-By-Mail.aspx' ),
		'id' => array( 'en' => 'You\'ll be asked for a photo ID, such as a Kentucky driver\'s license, a U.S. passport, or a military ID. If you can\'t get one for a reason the law lists, such as your work schedule, a lost ID or no transportation, you can sign an affirmation and vote, but you still have to show an ID card with your name and photo, or a county ID card approved by the State Board of Elections.', 'es' => 'Te pedirán una identificación con foto, como una licencia de conducir de Kentucky, un pasaporte de EE. UU. o una identificación militar. Si no puedes conseguir una por una razón que marca la ley, como tu horario de trabajo, haber perdido tu identificación o no tener transporte, puedes firmar una declaración y votar, pero igual tienes que mostrar una tarjeta de identificación con tu nombre y tu foto, o una identificación de un condado aprobada por la Junta Estatal de Elecciones (State Board of Elections).', 'src' => 'https://apps.legislature.ky.gov/law/statutes/statute.aspx?id=58074' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 5, 2026, and Kentucky has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 5 de octubre de 2026, y Kentucky no tiene registro el Día de las Elecciones.', 'src' => 'https://elect.ky.gov/Voters/Pages/Voting-In-Person-and-By-Mail.aspx' ),
	),
	'LA' => array(
		'polls' => array( 'en' => 'Polls are open 6 a.m. to 8 p.m.', 'es' => 'Los lugares de votación abren de 6 a. m. a 8 p. m.', 'src' => 'https://www.sos.la.gov/elections-voting/election-dates' ),
		'id' => array( 'en' => 'You\'ll be asked for a photo ID with your signature, such as a Louisiana driver\'s license or special ID card. Without one, you can sign a voter affidavit and vote.', 'es' => 'Te pedirán una identificación con foto y tu firma, como una licencia de conducir de Louisiana o una tarjeta de identificación especial. Si no tienes una, puedes firmar una declaración jurada de votante y votar.', 'src' => 'https://www.sos.la.gov/elections-voting/ways-to-vote' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadlines were October 5 in person or by mail and October 13, 2026 online, and Louisiana has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. Las fechas límite fueron el 5 de octubre en persona o por correo y el 13 de octubre de 2026 en línea, y Louisiana no tiene registro el Día de las Elecciones.', 'src' => 'https://www.sos.la.gov/elections-voting/election-dates' ),
	),
	'ME' => array(
		'polls' => array( 'en' => 'Polls close at 8 p.m. Each town sets its opening time, between 6 a.m. and 8 a.m., or as late as 10 a.m. in towns with fewer than 500 people.', 'es' => 'Los lugares de votación cierran a las 8 p. m. Cada municipio fija su hora de apertura, entre las 6 a. m. y las 8 a. m., o hasta las 10 a. m. en municipios de menos de 500 habitantes.', 'src' => 'https://legislature.maine.gov/statutes/21-A/title21-Asec626.html' ),
		'id' => array( 'en' => 'No, if you\'re already registered. You state your name and address to the election clerk. If you register in person, you must show proof of identity and residence.', 'es' => 'No, si ya estás registrado. Le dices tu nombre y tu dirección al empleado electoral. Si te registras en persona, debes mostrar un comprobante de identidad y de domicilio.', 'src' => 'https://legislature.maine.gov/statutes/21-A/title21-Asec671.html' ),
		'reg' => array( 'en' => 'Yes. Mail and online registration closed October 13, 2026, but you can register in person with your town\'s registrar through Election Day, including at the polls.', 'es' => 'Sí. El registro por correo y en línea cerró el 13 de octubre de 2026, pero puedes registrarte en persona con el registrador de tu municipio hasta el Día de las Elecciones, incluso en el lugar de votación.', 'src' => 'https://legislature.maine.gov/statutes/21-A/title21-Asec121-A-3.html' ),
	),
	'MD' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 8 p.m.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m.', 'src' => 'https://elections.maryland.gov/elections/2026/index.html' ),
		'id' => array( 'en' => 'Usually not. Some first-time voters are asked for ID, such as a Maryland driver\'s license, a student ID, or a utility bill.', 'es' => 'Por lo general, no. A algunos votantes nuevos se les pide una identificación, como una licencia de conducir de Maryland, una identificación de estudiante o un recibo de servicios.', 'src' => 'https://elections.maryland.gov/voting/election_day_questions.html' ),
		'reg' => array( 'en' => 'Yes. The advance deadline was October 13, 2026, but you can register and vote during early voting or at your polling place on Election Day. Bring a document that shows where you live.', 'es' => 'Sí. La fecha límite anticipada fue el 13 de octubre de 2026, pero puedes registrarte y votar durante la votación anticipada o en tu lugar de votación el Día de las Elecciones. Lleva un documento que muestre tu domicilio.', 'src' => 'https://elections.maryland.gov/voter_registration/index.html' ),
		'selfie' => array( 'en' => 'Yes, for personal use. You can photograph your own marked ballot before you cast it. Otherwise, phones and cameras can\'t be used in polling places.', 'es' => 'Sí, para uso personal. Puedes tomarle foto a tu propia boleta marcada antes de depositarla. Fuera de eso, no se pueden usar celulares ni cámaras en los lugares de votación.', 'src' => 'https://elections.maryland.gov/voting/election_day_questions.html' ),
	),
	'MA' => array(
		'polls' => array( 'en' => 'Polls close at 8 p.m. They open by 7 a.m., and some cities and towns open as early as 5:45 a.m.', 'es' => 'Los lugares de votación cierran a las 8 p. m. Abren a más tardar a las 7 a. m., y algunas ciudades y municipios abren desde las 5:45 a. m.', 'src' => 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleVIII/Chapter54/Section64' ),
		'id' => array( 'en' => 'Usually not. Some first-time voters who registered by mail must show a photo ID or a document like a utility bill, and poll workers may ask anyone for ID.', 'es' => 'Por lo general, no. Algunos votantes nuevos que se registraron por correo deben mostrar una identificación con foto o un documento como un recibo de servicios, y los trabajadores electorales pueden pedirle una identificación a cualquier votante.', 'src' => 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleVIII/Chapter54/Section76B' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was 5 p.m. on October 24, 2026 (or a mailed form postmarked that day), and Massachusetts has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 24 de octubre de 2026 a las 5 p. m. (o un formulario enviado por correo con matasellos de ese día), y Massachusetts no tiene registro el Día de las Elecciones.', 'src' => 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleVIII/Chapter51/Section26' ),
		'selfie' => array( 'en' => 'No. Massachusetts law makes it a crime to let anyone see how you marked your ballot for a purpose the law doesn\'t allow, and a photo you share would show it.', 'es' => 'No. En Massachusetts es un delito dejar que alguien vea cómo marcaste tu boleta con un fin que la ley no permite, y una foto que compartas lo mostraría.', 'src' => 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleVIII/Chapter56/Section25' ),
	),
	'MI' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 8 p.m. local time.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m., hora local.', 'src' => 'https://www.michigan.gov/sos/elections/voting/vote-on-election-day' ),
		'id' => array( 'en' => 'If you have a photo ID, such as a driver\'s license, a U.S. passport, or a student ID, you\'ll be asked to show it. If you don\'t have one, you can sign an affidavit and vote.', 'es' => 'Si tienes una identificación con foto, como una licencia de conducir, un pasaporte de EE. UU. o una identificación de estudiante, te pedirán que la muestres. Si no tienes una, puedes firmar una declaración jurada y votar.', 'src' => 'https://www.michigan.gov/sos/elections/voting/vote-on-election-day' ),
		'reg' => array( 'en' => 'Yes. Online and mail registration closed October 19, 2026. You can still register in person at your city or township clerk\'s office through 8 p.m. on Election Day, with proof of residency.', 'es' => 'Sí. El registro en línea y por correo cerró el 19 de octubre de 2026. Todavía puedes registrarte en persona en la oficina del secretario de tu ciudad o municipio (clerk) hasta las 8 p. m. del Día de las Elecciones, con un comprobante de domicilio.', 'src' => 'https://www.michigan.gov/sos/elections/voting/register-to-vote' ),
	),
	'MN' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 8 p.m. Some small towns open later, but no later than 10 a.m.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m. Algunos pueblos pequeños abren más tarde, pero no después de las 10 a. m.', 'src' => 'https://www.revisor.mn.gov/statutes/cite/204C.05' ),
		'id' => array( 'en' => 'No, if you\'re already registered; you sign the polling place roster. If you register at the polls, you\'ll need proof of where you live.', 'es' => 'No, si ya estás registrado; firmas la lista de votantes del lugar de votación. Si te registras ahí, necesitarás un comprobante de domicilio.', 'src' => 'https://www.revisor.mn.gov/statutes/cite/204C.10' ),
		'reg' => array( 'en' => 'Yes. Preregistration closed October 13, 2026, but you can register at your polling place on Election Day. Bring proof of where you live.', 'es' => 'Sí. El registro previo cerró el 13 de octubre de 2026, pero puedes registrarte en tu lugar de votación el Día de las Elecciones. Lleva un comprobante de domicilio.', 'src' => 'https://www.revisor.mn.gov/statutes/cite/201.061' ),
		'selfie' => array( 'en' => 'Not at the polls. If you show your marked ballot to anyone at the polling place, election judges set it aside as spoiled.', 'es' => 'No en el lugar de votación. Si le muestras tu boleta marcada a alguien en el lugar de votación, los jueces electorales la anulan.', 'src' => 'https://www.revisor.mn.gov/statutes/cite/204C.17' ),
	),
	'MS' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 7 p.m.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m.', 'src' => 'https://www.sos.ms.gov/content/documents/elections/2026%20Elections%20Calendar.pdf' ),
		'id' => array( 'en' => 'Yes. Show a photo ID, such as a Mississippi driver\'s license or a U.S. passport. Without one, you vote an affidavit ballot and have five business days to show ID.', 'es' => 'Sí. Muestra una identificación con foto, como una licencia de conducir de Mississippi o un pasaporte de EE. UU. Si no tienes una, votas con una boleta de declaración jurada (affidavit ballot) y tienes cinco días hábiles para mostrar tu identificación.', 'src' => 'https://www.msvoterid.ms.gov/' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 5, 2026, and Mississippi has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 5 de octubre de 2026, y Mississippi no tiene registro el Día de las Elecciones.', 'src' => 'https://www.sos.ms.gov/content/documents/elections/2026%20Elections%20Calendar.pdf' ),
	),
	'MO' => array(
		'polls' => array( 'en' => 'Polls are open 6 a.m. to 7 p.m. If you\'re in line at 7 p.m., you can still vote.', 'es' => 'Los lugares de votación abren de 6 a. m. a 7 p. m. Si estás en la fila a las 7 p. m., todavía puedes votar.', 'src' => 'https://www.sos.mo.gov/elections/goVoteMissouri/howtovote' ),
		'id' => array( 'en' => 'Yes. Show a photo ID, such as a Missouri driver\'s license or a U.S. passport. Without one, you vote a provisional ballot, which counts if you come back with ID that day or your signature matches.', 'es' => 'Sí. Muestra una identificación con foto, como una licencia de conducir de Missouri o un pasaporte de EE. UU. Si no tienes una, votas con una boleta provisional, que cuenta si regresas con tu identificación ese mismo día o si tu firma coincide.', 'src' => 'https://www.sos.mo.gov/elections/goVoteMissouri/howtovote' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 7, 2026, and Missouri has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 7 de octubre de 2026, y Missouri no tiene registro el Día de las Elecciones.', 'src' => 'https://www.sos.mo.gov/elections/calendar/2026cal' ),
		'selfie' => array( 'en' => 'No. Missouri law makes it an election offense to let anyone see your ballot so they know how you voted, and a photo you share would do that.', 'es' => 'No. En Missouri es un delito electoral dejar que alguien vea tu boleta para que sepa cómo votaste, y una foto que compartas lo haría.', 'src' => 'https://revisor.mo.gov/main/OneSection.aspx?section=115.637' ),
	),
	'OR' => array(
		'mail' => array( 'en' => 'Oregon votes by mail. Drop your ballot at a drop box or county elections office by 8 p.m. on Election Day, or mail it postmarked by Election Day so it arrives within seven days.', 'es' => 'Oregon vota por correo. Deja tu boleta en un buzón de entrega o en la oficina electoral de tu condado a más tardar a las 8 p. m. del Día de las Elecciones, o envíala con matasellos del Día de las Elecciones o antes para que llegue en un plazo de siete días.', 'src' => 'https://sos.oregon.gov/elections/Pages/faq.aspx' ),
		'id' => array( 'en' => 'No. Oregon votes by mail, and your county checks the signature on your ballot envelope against your registration.', 'es' => 'No. Oregon vota por correo, y tu condado compara la firma del sobre de tu boleta con la de tu registro.', 'src' => 'https://sos.oregon.gov/elections/Pages/faq.aspx' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 13, 2026, and Oregon has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 13 de octubre de 2026, y Oregon no tiene registro el Día de las Elecciones.', 'src' => 'https://sos.oregon.gov/elections/Pages/faq.aspx' ),
	),
	'PA' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 8 p.m.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m.', 'src' => 'https://www.pa.gov/agencies/vote/elections/upcoming-elections' ),
		'id' => array( 'en' => 'Usually not. If it\'s your first time voting at your polling place, bring an ID, such as a driver\'s license or a utility bill.', 'es' => 'Por lo general, no. Si es la primera vez que votas en tu lugar de votación, lleva una identificación, como una licencia de conducir o un recibo de servicios.', 'src' => 'https://www.pa.gov/agencies/vote/voter-support/elections-faqs' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 19, 2026, and Pennsylvania has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 19 de octubre de 2026, y Pennsylvania no tiene registro el Día de las Elecciones.', 'src' => 'https://www.pa.gov/agencies/vote/elections/upcoming-elections' ),
	),
	'RI' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 8 p.m. In New Shoreham, on Block Island, they open at 9 a.m.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m. En New Shoreham, en Block Island, abren a las 9 a. m.', 'src' => 'https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf' ),
		'id' => array( 'en' => 'Bring a photo ID, such as a Rhode Island driver\'s license, a free voter ID card, or a U.S. passport. Without one, you vote an emergency mail ballot during early voting, or a provisional ballot on Election Day that counts if your signature matches.', 'es' => 'Lleva una identificación con foto, como una licencia de conducir de Rhode Island, una credencial gratuita de votante o un pasaporte de EE. UU. Si no tienes una, votas con una boleta de emergencia por correo durante la votación anticipada, o con una boleta provisional el Día de las Elecciones que cuenta si tu firma coincide.', 'src' => 'https://vote.sos.ri.gov/Voter/PersonVotingPage' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 4, 2026. Rhode Island allows Election Day registration only in presidential elections, and then only to vote for president and vice president.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 4 de octubre de 2026. Rhode Island permite registrarse el Día de las Elecciones solo en elecciones presidenciales, y solo para votar por presidente y vicepresidente.', 'src' => 'https://vote.sos.ri.gov/Voter/VoteByMail' ),
		'selfie' => array( 'en' => 'Yes. The Board of Elections\' poll worker manual says photos of your own ballot are allowed. Phone calls inside the polling place aren\'t, unless they\'re about the election.', 'es' => 'Sí. El manual para trabajadores electorales de la Junta Electoral (Board of Elections) dice que se permiten fotos de tu propia boleta. Las llamadas dentro del lugar de votación no se permiten, salvo que sean sobre la elección.', 'src' => 'https://elections.ri.gov/sites/g/files/xkgbur756/files/2024-08/Poll%20worker%20Manual%20Updated%20July%202024.pdf' ),
	),
	'SC' => array(
		'polls' => array( 'en' => 'Polling places are open 7 a.m. to 7 p.m. If you\'re in line at 7 p.m., you can vote.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m. Si estás en la fila a las 7 p. m., puedes votar.', 'src' => 'https://scvotes.gov/voters/how-to-vote/' ),
		'id' => array( 'en' => 'You\'ll be asked for a photo ID, such as a South Carolina driver\'s license or a U.S. passport. If you can\'t get one, bring your voter registration card and sign an affidavit.', 'es' => 'Te pedirán una identificación con foto, como una licencia de conducir de South Carolina o un pasaporte de EE. UU. Si no puedes conseguir una, lleva tu tarjeta de registro de votante y firma una declaración jurada.', 'src' => 'https://scvotes.gov/voters/voter-faq/' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. Online registration closed October 4, 2026, and South Carolina has no same-day registration.', 'es' => 'No para la elección del 3 de noviembre. El registro en línea cerró el 4 de octubre de 2026, y South Carolina no tiene registro el mismo día.', 'src' => 'https://scvotes.gov/voters/2026prep/' ),
		'selfie' => array( 'en' => 'No. South Carolina law makes it unlawful to let anyone see your ballot.', 'es' => 'No. En South Carolina es ilegal dejar que alguien vea tu boleta.', 'src' => 'https://www.scstatehouse.gov/code/t07c025.php' ),
	),
	'SD' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 7 p.m. local time. South Dakota has two time zones.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m., hora local. South Dakota tiene dos zonas horarias.', 'src' => 'https://sdsos.gov/elections-voting/voting/default.aspx' ),
		'id' => array( 'en' => 'You\'ll be asked for a photo ID, such as a South Dakota driver\'s license. Without one, you can sign an affidavit and still vote a regular ballot.', 'es' => 'Te pedirán una identificación con foto, como una licencia de conducir de South Dakota. Si no tienes una, puedes firmar una declaración jurada y votar con una boleta regular.', 'src' => 'https://sdsos.gov/elections-voting/voting/voter-id.aspx' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. Your signed form had to reach your county auditor by October 19, 2026, and South Dakota has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. Tu formulario firmado tenía que llegar al auditor de tu condado (county auditor) a más tardar el 19 de octubre de 2026, y South Dakota no tiene registro el Día de las Elecciones.', 'src' => 'https://sdsos.gov/elections-voting/voting/register-to-vote/default.aspx' ),
		'selfie' => array( 'en' => 'Don\'t share one. South Dakota law bars showing anyone your marked ballot in a way that reveals your votes.', 'es' => 'No la compartas. La ley de South Dakota prohíbe mostrarle a cualquier persona tu boleta marcada de una forma que revele tus votos.', 'src' => 'https://sdlegislature.gov/Statutes/12-18-27' ),
	),
	'TN' => array(
		'polls' => array( 'en' => 'Opening times vary by county. All polls close at 8 p.m. Eastern or 7 p.m. Central time.', 'es' => 'La hora de apertura cambia según el condado. Todos los lugares de votación cierran a las 8 p. m., hora del Este, o a las 7 p. m., hora del Centro.', 'src' => 'https://sos.tn.gov/newsroom/press-releases/everything-voters-need-to-know-for-the-august-6-election-this-thursday' ),
		'id' => array( 'en' => 'Yes. Show a federal or Tennessee photo ID, such as a Tennessee driver\'s license, a U.S. passport, or a military ID.', 'es' => 'Sí. Muestra una identificación con foto federal o de Tennessee, como una licencia de conducir de Tennessee, un pasaporte de EE. UU. o una identificación militar.', 'src' => 'https://sos.tn.gov/elections/voter-id-requirements' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 5, 2026, and Tennessee has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 5 de octubre de 2026, y Tennessee no tiene registro el Día de las Elecciones.', 'src' => 'https://sos.tn.gov/newsroom/press-releases/tennessee-secretary-of-state-tre-hargett-reminds-eligible-tennesseans-today' ),
		'selfie' => array( 'en' => 'Not at the polls. Tennessee law lets you use your phone in the polling place for voting information, but not to take photos or video.', 'es' => 'No en el lugar de votación. La ley de Tennessee te permite usar tu celular en el lugar de votación para consultar información sobre tu voto, pero no para tomar fotos ni video.', 'src' => 'https://www.tn.gov/content/dam/tn/attorneygeneral/documents/ops/2016/op16-049.pdf' ),
	),
	'TX' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 7 p.m. local time. Texas has two time zones.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m., hora local. Texas tiene dos zonas horarias.', 'src' => 'https://www.votetexas.gov/faq/index.html' ),
		'id' => array( 'en' => 'Show one of seven accepted photo IDs, such as a Texas driver\'s license or a U.S. passport. If you can\'t reasonably get one, you can sign a Reasonable Impediment Declaration and show supporting ID, such as your voter registration certificate.', 'es' => 'Muestra una de las siete identificaciones con foto aceptadas, como una licencia de conducir de Texas o un pasaporte de EE. UU. Si no puedes conseguir una por una razón válida, puedes firmar una declaración de impedimento razonable (Reasonable Impediment Declaration) y mostrar un documento de apoyo, como tu certificado de registro de votante.', 'src' => 'https://www.votetexas.gov/faq/index.html' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 5, 2026, and Texas has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 5 de octubre de 2026, y Texas no tiene registro el Día de las Elecciones.', 'src' => 'https://www.votetexas.gov/register-to-vote/index.html' ),
		'selfie' => array( 'en' => 'Not at the polls. Texas law bars recording images within 100 feet of a voting station.', 'es' => 'No en el lugar de votación. La ley de Texas prohíbe grabar imágenes a menos de 100 pies de una cabina de votación.', 'src' => 'https://statutes.capitol.texas.gov/Docs/EL/htm/EL.61.htm' ),
	),
	'UT' => array(
		'polls' => array( 'en' => 'Polling places are open 7 a.m. to 8 p.m. Utah also mails ballots to voters. Your mail ballot must reach the county clerk by 8 p.m. on November 3, and a postmark isn\'t enough.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m. Utah también envía boletas por correo a los votantes. Tu boleta por correo debe llegar a la oficina del secretario del condado (county clerk) a más tardar a las 8 p. m. del 3 de noviembre, y el matasellos no basta.', 'src' => 'https://vote.utah.gov/learn-about-voting-by-mail-and-absentee-voting/' ),
		'id' => array( 'en' => 'Yes, to vote in person. Show one photo ID, such as a Utah driver\'s license or a U.S. passport, or two documents that together prove your name and address.', 'es' => 'Sí, para votar en persona. Muestra una identificación con foto, como una licencia de conducir de Utah o un pasaporte de EE. UU., o dos documentos que juntos comprueben tu nombre y tu dirección.', 'src' => 'https://vote.utah.gov/voter-id/' ),
		'reg' => array( 'en' => 'Yes. The regular deadline, for registrations to reach your county clerk, was 5 p.m. on October 23, 2026. You can still register in person during early voting or on Election Day with two forms of ID.', 'es' => 'Sí. La fecha límite regular para que tu registro llegara a la oficina del secretario de tu condado fue a las 5 p. m. del 23 de octubre de 2026. Todavía puedes registrarte en persona durante la votación anticipada o el Día de las Elecciones con dos formas de identificación.', 'src' => 'https://vote.utah.gov/current-election-information/' ),
		'selfie' => array( 'en' => 'Yes. Utah law lets you photograph your own ballot and share it. Photographing someone else\'s ballot at a polling place is a misdemeanor.', 'es' => 'Sí. La ley de Utah te permite tomarle foto a tu propia boleta y compartirla. Tomarle foto a la boleta de otra persona en un lugar de votación es un delito menor.', 'src' => 'https://le.utah.gov/xcode/Title20A/Chapter3a/20A-3a-S504.html' ),
	),
	'VT' => array(
		'polls' => array( 'en' => 'Polls open between 5 a.m. and 10 a.m., depending on the town, and close at 7 p.m. Vermont also mails a ballot to every active voter. Return it to your town clerk or drop box by the day before the election, mail it so the clerk gets it before the polls close, or bring it to your polling place by 7 p.m.', 'es' => 'Los lugares de votación abren entre las 5 a. m. y las 10 a. m., según el municipio, y cierran a las 7 p. m. Vermont también envía una boleta por correo a cada votante activo. Devuélvela al secretario de tu municipio (town clerk) o al buzón de entrega a más tardar el día antes de la elección, mándala por correo para que el secretario la reciba antes de que cierren los lugares de votación, o llévala a tu lugar de votación antes de las 7 p. m.', 'src' => 'https://legislature.vermont.gov/statutes/section/17/051/02543' ),
		'id' => array( 'en' => 'Usually not. If you registered for the first time by mail or online, you must include a copy of an ID, such as a driver\'s license or utility bill, with your application.', 'es' => 'Por lo general, no. Si te registraste por primera vez por correo o en línea, debes incluir una copia de una identificación, como una licencia de conducir o un recibo de servicios, con tu solicitud.', 'src' => 'https://sos.vermont.gov/elections/voters/registration/' ),
		'reg' => array( 'en' => 'Yes. You can register at your town or city clerk\'s office during business hours before the election, or at your polling place on Election Day.', 'es' => 'Sí. Puedes registrarte en la oficina del secretario de tu municipio o ciudad en horario de oficina antes de la elección, o en tu lugar de votación el Día de las Elecciones.', 'src' => 'https://sos.vermont.gov/elections/voters/registration/' ),
	),
	'VA' => array(
		'polls' => array( 'en' => 'Polling places are open 6 a.m. to 7 p.m. If you\'re in line at 7 p.m., you can vote.', 'es' => 'Los lugares de votación abren de 6 a. m. a 7 p. m. Si estás en la fila a las 7 p. m., puedes votar.', 'src' => 'https://www.elections.virginia.gov/casting-a-ballot/' ),
		'id' => array( 'en' => 'Show an acceptable ID, which doesn\'t need a photo. If you don\'t have one, you can sign an ID Confirmation Statement and vote a regular ballot.', 'es' => 'Muestra una identificación aceptada, que no necesita tener foto. Si no tienes una, puedes firmar una declaración de confirmación de identidad (ID Confirmation Statement) y votar con una boleta regular.', 'src' => 'https://www.elections.virginia.gov/casting-a-ballot/in-person-voting/' ),
		'reg' => array( 'en' => 'Yes. The regular deadline was October 23, 2026. You can still register in person and vote a provisional ballot through Election Day.', 'es' => 'Sí. La fecha límite regular fue el 23 de octubre de 2026. Todavía puedes registrarte en persona y votar con una boleta provisional hasta el Día de las Elecciones.', 'src' => 'https://www.elections.virginia.gov/casting-a-ballot/calendars-schedules/upcoming-elections.html' ),
	),
	'WA' => array(
		'mail' => array( 'en' => 'Washington votes by mail. Put your ballot in an official drop box by 8 p.m. on Election Day, or mail it with a postmark dated Election Day or earlier. The state recommends mailing it a week early.', 'es' => 'Washington vota por correo. Deja tu boleta en un buzón de entrega oficial a más tardar a las 8 p. m. del Día de las Elecciones, o envíala con matasellos del Día de las Elecciones o antes. El estado recomienda enviarla con una semana de anticipación.', 'src' => 'https://app.leg.wa.gov/RCW/default.aspx?cite=29A.60.190' ),
		'id' => array( 'en' => 'No. Washington votes by mail and checks your signature. At a voting center, staff check your signature or ID before you use an accessible voting unit.', 'es' => 'No. Washington vota por correo y revisa tu firma. En un centro de votación, el personal revisa tu firma o tu identificación antes de que uses un equipo de votación accesible.', 'src' => 'https://www.sos.wa.gov/elections/voters/helpful-information/frequently-asked-questions-about-elections' ),
		'reg' => array( 'en' => 'Yes. Online and mail registrations must arrive by October 26, 2026, and you can register in person until 8 p.m. on Election Day.', 'es' => 'Sí. Los registros en línea y por correo deben llegar a más tardar el 26 de octubre de 2026, y puedes registrarte en persona hasta las 8 p. m. del Día de las Elecciones.', 'src' => 'https://www.sos.wa.gov/elections/voters/voter-registration/register-vote-washington-state', 'until' => '2026-10-26', 'en_after' => 'Yes, in person. Online and mail registrations had to arrive by October 26, 2026. You can still register in person until 8 p.m. on Election Day.', 'es_after' => 'Sí, en persona. Los registros en línea y por correo tenían que llegar a más tardar el 26 de octubre de 2026. Todavía puedes registrarte en persona hasta las 8 p. m. del Día de las Elecciones.' ),
		'selfie' => array( 'en' => 'Yes. Washington doesn\'t prohibit ballot selfies. It\'s illegal to view someone else\'s ballot for a purpose such as vote buying.', 'es' => 'Sí. Washington no prohíbe las selfies con la boleta. Es ilegal ver la boleta de otra persona con un fin como comprar votos.', 'src' => 'https://www.sos.wa.gov/elections/voters/helpful-information/frequently-asked-questions-about-elections' ),
	),
	'WV' => array(
		'polls' => array( 'en' => 'Polls are open 6:30 a.m. to 7:30 p.m. at your assigned polling place.', 'es' => 'Los lugares de votación abren de 6:30 a. m. a 7:30 p. m. en el lugar que te corresponde.', 'src' => 'https://sos.wv.gov/elections/voter-information/elections-frequently-asked-questions-faqs' ),
		'id' => array( 'en' => 'Yes. Show an unexpired photo ID, such as a West Virginia driver\'s license, a U.S. passport, or a West Virginia student ID. Without one, an adult or poll worker who has known you for six months can vouch for you; otherwise you vote a provisional ballot.', 'es' => 'Sí. Muestra una identificación vigente con foto, como una licencia de conducir de West Virginia, un pasaporte de EE. UU. o una identificación de estudiante de West Virginia. Si no tienes una, un adulto o un trabajador electoral que te conozca desde hace seis meses puede dar fe de quién eres; si no, votas con una boleta provisional.', 'src' => 'https://sos.wv.gov/be-registered-and-ready' ),
		'reg' => array( 'en' => 'No, not for the November 3 election. The deadline was October 13, 2026, and West Virginia has no Election Day registration.', 'es' => 'No para la elección del 3 de noviembre. La fecha límite fue el 13 de octubre de 2026, y West Virginia no tiene registro el Día de las Elecciones.', 'src' => 'https://sos.wv.gov/govotewv' ),
		'selfie' => array( 'en' => 'Not in the voting booth. West Virginia law bars taking a recording device into the booth to record voting.', 'es' => 'No en la cabina de votación. La ley de West Virginia prohíbe entrar a la cabina con un aparato de grabación para grabar la votación.', 'src' => 'https://code.wvlegislature.gov/3-4A-23/' ),
	),
	'WI' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 8 p.m. Absentee ballots must reach your municipal clerk by 8 p.m. on Election Day.', 'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m. Las boletas de voto en ausencia deben llegar al secretario de tu municipio (municipal clerk) a más tardar a las 8 p. m. del Día de las Elecciones.', 'src' => 'https://myvote.wi.gov/en-us/Voter-Deadlines' ),
		'id' => array( 'en' => 'Yes. Show an acceptable photo ID, such as a Wisconsin driver\'s license, a free state ID card, or a U.S. passport. Without one, you vote a provisional ballot and must show ID afterward.', 'es' => 'Sí. Muestra una identificación con foto aceptada, como una licencia de conducir de Wisconsin, una tarjeta de identificación estatal gratuita o un pasaporte de EE. UU. Si no tienes una, votas con una boleta provisional y debes mostrar tu identificación después.', 'src' => 'https://elections.wi.gov/voters/photo-id/photo-id-bring-it-ballot' ),
		'reg' => array( 'en' => 'Yes. Online and mail registration closed October 14, 2026. You can register at your clerk\'s office until 5 p.m. on October 30, or at your polling place on Election Day. Bring proof of where you live.', 'es' => 'Sí. El registro en línea y por correo cerró el 14 de octubre de 2026. Puedes registrarte en la oficina del secretario municipal hasta las 5 p. m. del 30 de octubre, o en tu lugar de votación el Día de las Elecciones. Lleva un comprobante de domicilio.', 'src' => 'https://myvote.wi.gov/en-us/Voter-Deadlines', 'until' => '2026-10-30', 'en_after' => 'Yes, at your polling place on Election Day. Online and mail registration closed October 14, 2026, and registration at your clerk\'s office ended at 5 p.m. on October 30. Bring proof of where you live.', 'es_after' => 'Sí, en tu lugar de votación el Día de las Elecciones. El registro en línea y por correo cerró el 14 de octubre de 2026, y el registro en la oficina del secretario municipal terminó a las 5 p. m. del 30 de octubre. Lleva un comprobante de domicilio.' ),
		'selfie' => array( 'en' => 'No. Wisconsin law makes it an offense to show your marked ballot to anyone, and a photo you share would do that.', 'es' => 'No. En Wisconsin es un delito mostrarle tu boleta marcada a cualquier persona, y una foto que compartas lo haría.', 'src' => 'https://docs.legis.wisconsin.gov/statutes/statutes/12/13' ),
	),
	'WY' => array(
		'polls' => array( 'en' => 'Polls are open 7 a.m. to 7 p.m. If you\'re in line at 7 p.m., you can still vote.', 'es' => 'Los lugares de votación abren de 7 a. m. a 7 p. m. Si estás en la fila a las 7 p. m., todavía puedes votar.', 'src' => 'https://sos.wyo.gov/faqs.aspx?root=ELEC' ),
		'id' => array( 'en' => 'Yes. Show an acceptable ID, such as a Wyoming driver\'s license or ID card, a U.S. passport, a tribal ID, or a Medicare or Medicaid card.', 'es' => 'Sí. Muestra una identificación aceptada, como una licencia de conducir o tarjeta de identificación de Wyoming, un pasaporte de EE. UU., una identificación tribal o una tarjeta de Medicare o Medicaid.', 'src' => 'https://sos.wyo.gov/Elections/Docs/2026/2026_Voter_Guide.pdf' ),
		'reg' => array( 'en' => 'Yes. Regular registration closed October 19, 2026, but you can register and vote at the same time during early absentee voting or on Election Day. Bring proof of identity, citizenship, and residence.', 'es' => 'Sí. El registro regular cerró el 19 de octubre de 2026, pero puedes registrarte y votar al mismo tiempo durante la votación anticipada en ausencia o el Día de las Elecciones. Lleva comprobantes de identidad, ciudadanía y domicilio.', 'src' => 'https://sos.wyo.gov/Elections/Docs/2026/2026_Key_Election_Dates.pdf' ),
	),
);
